<?php

use App\Http\Controllers\AuthController;
use App\Http\Controllers\ReservationController;
use App\Http\Controllers\RoleController;
use App\Http\Controllers\SpaceCatalogController;
use App\Http\Controllers\SpaceController;
use App\Http\Controllers\UserController;
use Illuminate\Support\Facades\Route;
use Inertia\Inertia;

Route::get('/', fn () => redirect()->route('login'));
Route::get('/login', [AuthController::class, 'create'])->name('login');
Route::post('/login', [AuthController::class, 'store'])->name('login.store');
Route::post('/logout', [AuthController::class, 'destroy'])->name('logout');
Route::middleware(['auth', 'access.session'])->group(function () {
    Route::get('/reservas', [ReservationController::class, 'index'])->name('reservas.index');
    Route::get('/reservas/crear', [ReservationController::class, 'create'])->middleware('can:reservas.solicitar')->name('reservas.create');
    Route::post('/reservas', [ReservationController::class, 'store'])->middleware('can:reservas.solicitar')->name('reservas.store');
    Route::get('/reservas/{reserva}', [ReservationController::class, 'show'])->whereNumber('reserva')->name('reservas.show');
    Route::post('/reservas/{reserva}/aprobar', [ReservationController::class, 'approve'])->whereNumber('reserva')->middleware('can:reservas.resolver')->name('reservas.approve');
    Route::post('/reservas/{reserva}/rechazar', [ReservationController::class, 'reject'])->whereNumber('reserva')->middleware('can:reservas.resolver')->name('reservas.reject');
    Route::post('/reservas/{reserva}/cancelar', [ReservationController::class, 'cancel'])->whereNumber('reserva')->name('reservas.cancel');
    Route::get('/disponibilidad', [SpaceController::class, 'availability'])->middleware('can:espacios.ver')->name('disponibilidad.index');
    Route::get('/espacios', [SpaceController::class, 'index'])->middleware('can:espacios.ver')->name('espacios.index');
    Route::get('/espacios/crear', [SpaceController::class, 'create'])->middleware('can:espacios.gestionar')->name('espacios.create');
    Route::post('/espacios', [SpaceController::class, 'store'])->middleware('can:espacios.gestionar')->name('espacios.store');
    Route::get('/espacios/catalogos/{catalogo}', [SpaceCatalogController::class, 'index'])->whereIn('catalogo', ['pisos', 'tipos', 'caracteristicas'])->middleware('can:espacios.gestionar')->name('espacios.catalogos');
    Route::post('/espacios/catalogos/{catalogo}', [SpaceCatalogController::class, 'save'])->whereIn('catalogo', ['pisos', 'tipos', 'caracteristicas'])->middleware('can:espacios.gestionar')->name('espacios.catalogos.store');
    Route::put('/espacios/catalogos/{catalogo}/{registro}', [SpaceCatalogController::class, 'save'])->whereIn('catalogo', ['pisos', 'tipos', 'caracteristicas'])->whereNumber('registro')->middleware('can:espacios.gestionar')->name('espacios.catalogos.update');
    Route::get('/espacios/{espacio}', [SpaceController::class, 'show'])->middleware('can:espacios.ver')->name('espacios.show');
    Route::get('/espacios/{espacio}/editar', [SpaceController::class, 'edit'])->middleware('can:espacios.gestionar')->name('espacios.edit');
    Route::put('/espacios/{espacio}', [SpaceController::class, 'update'])->middleware('can:espacios.gestionar')->name('espacios.update');
    Route::patch('/espacios/{espacio}/estado', [SpaceController::class, 'state'])->middleware('can:espacios.cambiar_estado')->name('espacios.state');
    Route::post('/espacios/{espacio}/bloqueos', [SpaceController::class, 'block'])->middleware('can:espacios.gestionar_bloqueos')->name('espacios.blocks.store');
    Route::patch('/espacios/{espacio}/bloqueos/{bloqueo}/desactivar', [SpaceController::class, 'deactivate'])->whereNumber('bloqueo')->middleware('can:espacios.gestionar_bloqueos')->name('espacios.blocks.deactivate');
    Route::get('/inicio', fn () => Inertia::render('Home'))->name('inicio');
    Route::get('/usuarios', [UserController::class, 'index'])->middleware('can:usuarios.ver')->name('usuarios.index');
    Route::get('/usuarios/crear', [UserController::class, 'create'])->middleware('can:usuarios.crear')->name('usuarios.create');
    Route::post('/usuarios', [UserController::class, 'store'])->middleware('can:usuarios.crear')->name('usuarios.store');
    Route::get('/usuarios/{usuario}', [UserController::class, 'show'])->middleware('can:usuarios.ver')->name('usuarios.show');
    Route::get('/usuarios/{usuario}/editar', [UserController::class, 'edit'])->middleware('can:usuarios.editar')->name('usuarios.edit');
    Route::put('/usuarios/{usuario}', [UserController::class, 'update'])->middleware('can:usuarios.editar')->name('usuarios.update');
    Route::patch('/usuarios/{usuario}/deshabilitar', [UserController::class, 'disable'])->middleware('can:usuarios.deshabilitar')->name('usuarios.disable');
    Route::get('/roles', [RoleController::class, 'index'])->middleware('can:roles.ver')->name('roles.index');
    Route::get('/roles/crear', [RoleController::class, 'create'])->middleware('can:roles.crear')->name('roles.create');
    Route::post('/roles', [RoleController::class, 'store'])->middleware('can:roles.crear')->name('roles.store');
    Route::get('/roles/{rol}', [RoleController::class, 'show'])->middleware('can:roles.ver')->name('roles.show');
    Route::get('/roles/{rol}/editar', [RoleController::class, 'edit'])->middleware('can:roles.editar')->name('roles.edit');
    Route::put('/roles/{rol}', [RoleController::class, 'update'])->middleware('can:roles.editar')->name('roles.update');
    Route::put('/roles/{rol}/permisos', [RoleController::class, 'permissions'])->middleware('can:roles.gestionar_permisos')->name('roles.permissions');
    Route::get('/permisos', [RoleController::class, 'catalog'])->middleware('can:permisos.ver')->name('permisos.index');
    Route::get('/asignaciones/candidatos', [RoleController::class, 'candidates'])->middleware('can:roles.asignar')->name('asignaciones.candidates');
    Route::post('/roles/{rol}/asignaciones', [RoleController::class, 'assign'])->middleware('can:roles.asignar')->name('asignaciones.store');
    Route::delete('/roles/{rol}/asignaciones', [RoleController::class, 'withdraw'])->middleware('can:roles.retirar')->name('asignaciones.destroy');
});
